def get_icon(name: str, size: int = 16, color: str = "currentColor") -> str:
    """Returns raw SVG string for an icon."""
    template = ICONS.get(name, ICONS["shield"])
    return template.format(size=size, color=color)

def render_icon_badge(icon_name: str, label: str, badge_type: str = "neutral", size: int = 14) -> str:
    """Renders an inline status pill with SVG icon."""
    color_map = {
        "green": "#10b981",
        "amber": "#f59e0b",
        "red": "#ef4444",
        "blue": "#38bdf8",
        "purple": "#c084fc",
        "neutral": "#94a3b8"
    }
    col = color_map.get(badge_type, "#94a3b8")
    svg_str = get_icon(icon_name, size=size, color=col)
    return f"""<span class="status-pill pill-{badge_type}">{svg_str} <span>{label}</span></span>"""
